REM *************************** Resetting values for IDENTITY columns

Prompt ******  Resetting values for IDENTITY columns ....

ALTER TABLE hotels MODIFY hotel_id GENERATED BY DEFAULT ON NULL AS IDENTITY ( START WITH LIMIT VALUE );
ALTER TABLE room_types MODIFY room_type_id GENERATED BY DEFAULT ON NULL AS IDENTITY ( START WITH LIMIT VALUE );
ALTER TABLE rooms MODIFY room_id GENERATED BY DEFAULT ON NULL AS IDENTITY ( START WITH LIMIT VALUE );
ALTER TABLE guests MODIFY guest_id GENERATED BY DEFAULT ON NULL AS IDENTITY ( START WITH LIMIT VALUE );
ALTER TABLE employees MODIFY employee_id GENERATED BY DEFAULT ON NULL AS IDENTITY ( START WITH LIMIT VALUE );
ALTER TABLE reservations MODIFY reservation_id GENERATED BY DEFAULT ON NULL AS IDENTITY ( START WITH LIMIT VALUE );
ALTER TABLE stays MODIFY stay_id GENERATED BY DEFAULT ON NULL AS IDENTITY ( START WITH LIMIT VALUE );
ALTER TABLE services MODIFY service_id GENERATED BY DEFAULT ON NULL AS IDENTITY ( START WITH LIMIT VALUE );
ALTER TABLE service_charges MODIFY charge_id GENERATED BY DEFAULT ON NULL AS IDENTITY ( START WITH LIMIT VALUE );
ALTER TABLE invoices MODIFY invoice_id GENERATED BY DEFAULT ON NULL AS IDENTITY ( START WITH LIMIT VALUE );
